export function ProjectSelector({ collapsed }: { collapsed: boolean }) {
  const selected = useAppStore((s) => s.selectedProject);
  const projects = useAppStore((s) => s.projects);

  const handleSelect = (id: string) => {
    useAppStore.getState().setSelectedProject(id);
  };

  return (
    <DropdownMenu>
      <DropdownMenuTrigger>{selected?.name || 'Select Project'}</DropdownMenuTrigger>
      <DropdownMenuContent>
        {projects.map((project) => (
          <DropdownMenuItem
            key={project.id}
            onClick={() => handleSelect(project.id)}
          >
            {project.name}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

