const VALID_TRANSITIONS: Record<string, string[]> = {
  backlog: ['pending', 'failed'],
  pending: ['in_progress', 'failed'],
  in_progress: ['waiting_approval', 'failed'],
  waiting_approval: ['verified', 'failed'],
  verified: [],
  failed: []
};
// In handleDragEnd:
const allowedTransitions = VALID_TRANSITIONS[currentStatus];
if (!allowedTransitions?.includes(newStatus)) {
  toast.error(`Cannot move from ${currentStatus} to ${newStatus}`);
  return;
}

const FeatureCard = ({ feature }) => {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: feature.id });
  const style = { transform: CSS.Transform.toString(transform), transition, opacity: isDragging ? 0.5 : 1 };
  return <Card ref={setNodeRef} style={style} className="cursor-grab active:cursor-grabbing" {...attributes} {...listeners}>
    <CardHeader><CardTitle>{feature.title}</CardTitle></CardHeader>
  </Card>;
};

const KanbanColumn = ({ status, title, features, color }) => {
  const { setNodeRef, isOver } = useDroppable({ id: status });
  return <div ref={setNodeRef} className={cn('flex flex-col', isOver && 'bg-accent/30')}>
    <div className="flex items-center gap-2"><div className={`h-2 w-2 rounded-full ${color}`} /><h3>{title}</h3></div>
    <SortableContext items={features.map(f => f.id)} strategy={verticalListSortingStrategy}>
      <div className="flex flex-1 flex-col gap-2">
        {features.map(f => <FeatureCard key={f.id} feature={f} />)}
      </div>
    </SortableContext>
  </div>;
};

const queryClient = useQueryClient();
const updateStatus = useMutation(
  orpc.features.updateStatus.mutationOptions({
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: orpc.features.list.queryOptions().queryKey });
      toast.success('Feature status updated');
    },
    onError: (error) => {
      toast.error(error.message || 'Failed to update feature status');
    }
  })
);
const handleStatusChange = (id: string, status: string) => {
  updateStatus.mutate({ id, status: status as FeatureStatus });
};
